def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    last_my, last_opp = history[-1]

    # Final round: D is weakly dominant against the opponent's final action.
    if n == 99:
        return 'D'

    opp_c = 0
    my_d = 0
    for a, b in history:
        if b == 'C':
            opp_c += 1
        if a == 'D':
            my_d += 1

    opp_d = n - opp_c
    coop_rate = opp_c / n

    r = 10 if n >= 10 else n
    recent_opp_c = 0
    for i in range(n - r, n):
        if history[i][1] == 'C':
            recent_opp_c += 1
    recent_coop = recent_opp_c / r

    opp_d_run = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_d_run += 1
        else:
            break

    resp_total = 0
    resp_c = 0
    unprov = 0

    # Track how the opponent responds after our previous defection, and count
    # unprovoked opponent defections that are not delayed retaliation.
    for i in range(1, n):
        if history[i - 1][0] == 'D':
            resp_total += 1
            if history[i][1] == 'C':
                resp_c += 1

        if history[i - 1][0] == 'C' and history[i][1] == 'D':
            if i < 2 or history[i - 2][0] != 'D':
                unprov += 1

    # Defectors or clearly hostile patterns are met with D.
    if (coop_rate < 0.25 or
            recent_coop < 0.25 or
            opp_d_run >= 5 or
            unprov >= max(5, n // 8)):
        return 'D'

    resp_soft = resp_c / resp_total if resp_total else 0.0
    max_d_for_exploit = max(3, n // 25)

    # Opponent has repeatedly responded to our D with C: safe to exploit.
    exploitable = (
        resp_total >= 1 and
        resp_c == resp_total and
        coop_rate >= 0.55 and
        opp_d <= max_d_for_exploit and
        recent_coop >= 0.5
    )

    # Opponent tends to punish our D: stay cooperative after one provocation.
    retaliatory = resp_total >= 2 and resp_soft <= 0.45

    if exploitable and last_opp == 'C' and recent_coop >= 0.5:
        return 'D'

    if last_opp == 'D':
        if last_my == 'D':
            # Mutual D after nice play is often a delayed punishment; reset.
            if coop_rate >= 0.55 and recent_coop >= 0.45 and unprov <= 2:
                return 'C'
            if resp_total >= 1 and resp_soft >= 0.7 and opp_d <= max_d_for_exploit:
                return 'C'
            return 'D'

        # Opponent D after our C, but it followed our D one round earlier:
        # likely retaliation for our own provocation.
        if n >= 2 and history[-2][0] == 'D':
            if coop_rate >= 0.40 and recent_coop >= 0.35:
                return 'C'
            return 'D'

        # Slightly extended delayed punishment.
        if (n >= 3 and opp_d_run <= 2 and
                history[-3][0] == 'D' and
                coop_rate >= 0.55 and recent_coop >= 0.45):
            return 'C'

        # Unprovoked opponent D: punish.
        return 'D'

    # last_opp == 'C'
    if last_my == 'D':
        # We defected and opponent cooperated. If not proven exploitable,
        # apologize to avoid revenge spirals with retaliators.
        if my_d == 1 and n >= 60 and opp_d == 0 and coop_rate == 1.0:
            if rng.random() < 0.35:
                return 'D'
        return 'C'

    # Stable mutual cooperation.
    # Force one exploratory D against pure-cooperation opponents before endgame.
    if my_d == 0 and opp_d == 0:
        if n >= 50:
            return 'D'
        if n >= 30 and rng.random() < 0.08:
            return 'D'

    # If no punishment evidence and opponent has been perfectly cooperative,
    # test lightly near the end.
    if not retaliatory and opp_d == 0 and coop_rate >= 0.95:
        if n >= 90 and rng.random() < 0.25:
            return 'D'

    return 'C'
